import type { DeepReadonly } from "@btst/stack/plugins/api";
import type { z } from "zod";
import type {
	createContactSchema,
	createCompanySchema,
	createDealSchema,
} from "./schemas";

/** Contact with arbitrary string custom fields and normalized tags. */
export type Contact = {
	id: string;
	firstName: string;
	lastName?: string | null;
	email?: string | null;
	phone?: string | null;
	company?: string | null;
	companyId?: string | null;
	title?: string | null;
	notes?: string | null;
	tags: string[];
	customFields: Record<string, string>;
	createdAt: string;
	updatedAt: string;
};
/** A company shared by contacts and deals. */
export type Company = {
	id: string;
	name: string;
	domain?: string | null;
	phone?: string | null;
	notes?: string | null;
	createdAt: string;
	updatedAt: string;
};
/** A deal's title and stage are projected from its Kanban task, avoiding duplicate state. */
export type Deal = {
	id: string;
	taskId: string;
	title: string;
	value?: number | null;
	currency: string;
	stage: string;
	pipelineId: string;
	contactId?: string | null;
	companyId?: string | null;
	closeDate?: string | null;
	status: "open" | "won" | "lost";
	createdAt: string;
	updatedAt: string;
};
/** A logged interaction or scheduled follow-up. */
export type Activity = {
	id: string;
	type: "note" | "call" | "email" | "meeting";
	body: string;
	contactId?: string | null;
	dealId?: string | null;
	dueAt?: string | null;
	completedAt?: string | null;
	remindedAt?: string | null;
	createdAt: string;
};
/** A CRM pipeline is an ordinary Kanban board. */
export type Pipeline = {
	deals: Deal[];
	id: string;
	name: string;
	slug: string;
	description?: string;
	ownerId?: string;
	organizationId?: string;
	createdAt: string;
	updatedAt: string;
	columns: {
		id: string;
		title: string;
		order: number;
		boardId: string;
		createdAt: string;
		updatedAt: string;
		tasks: {
			id: string;
			title: string;
			description?: string;
			priority: "LOW" | "MEDIUM" | "HIGH" | "URGENT";
			order: number;
			columnId: string;
			assigneeId?: string | null;
			completedAt?: string;
			isArchived: boolean;
			createdAt: string;
			updatedAt: string;
		}[];
	}[];
};
/** Hook context is supplied only after operation authorization. */
export interface CrmHookContext {
	readonly request?: Request;
}
type Hook<T> = (
	value: DeepReadonly<T>,
	context: CrmHookContext,
) => Promise<void> | void;
/** Lifecycle callbacks; reminder delivery is triggered by sendDueReminders in your scheduler. */
export interface CrmPluginHooks {
	onBeforeCreateContact?: Hook<z.output<typeof createContactSchema>>;
	onAfterCreateContact?: Hook<Contact>;
	onBeforeUpdateContact?: Hook<{
		id: string;
		data: Partial<z.output<typeof createContactSchema>>;
	}>;
	onAfterUpdateContact?: Hook<Contact>;
	onBeforeDeleteContact?: Hook<Contact>;
	onAfterDeleteContact?: Hook<{ id: string }>;
	onBeforeCreateCompany?: Hook<z.output<typeof createCompanySchema>>;
	onAfterCreateCompany?: Hook<Company>;
	onBeforeUpdateCompany?: Hook<{
		id: string;
		data: Partial<z.output<typeof createCompanySchema>>;
	}>;
	onAfterUpdateCompany?: Hook<Company>;
	onBeforeDeleteCompany?: Hook<Company>;
	onAfterDeleteCompany?: Hook<{ id: string }>;
	onBeforeCreateDeal?: Hook<z.output<typeof createDealSchema>>;
	onAfterCreateDeal?: Hook<Deal>;
	onBeforeUpdateDeal?: Hook<{
		id: string;
		data: Partial<z.output<typeof createDealSchema>>;
	}>;
	onAfterUpdateDeal?: Hook<Deal>;
	onBeforeDeleteDeal?: Hook<Deal>;
	onAfterDeleteDeal?: Hook<{ id: string }>;
	onBeforeLogActivity?: Hook<Omit<Activity, "id" | "createdAt">>;
	onAfterLogActivity?: Hook<Activity>;
	onAfterUpdateActivity?: Hook<Activity>;
	onAfterMoveDeal?: Hook<Deal>;
	/** Deliver the follow-up notification. Successful delivery is recorded to avoid repeat runs. */
	onActivityReminder?: Hook<Activity>;
}
/** Internal storage types; use operations rather than direct database access in requests. */
export interface ContactRecord
	extends Omit<Contact, "tags" | "customFields" | "createdAt" | "updatedAt"> {
	tags: string;
	customFields: string;
	createdAt: Date;
	updatedAt: Date;
}
/** Internal company storage. */
export interface CompanyRecord
	extends Omit<Company, "createdAt" | "updatedAt"> {
	createdAt: Date;
	updatedAt: Date;
}
/** Internal metadata for a Kanban-backed deal. */
export interface DealRecord
	extends Omit<
		Deal,
		"title" | "stage" | "pipelineId" | "createdAt" | "updatedAt" | "closeDate"
	> {
	closeDate?: Date | null;
	createdAt: Date;
	updatedAt: Date;
}
/** Internal activity storage. */
export interface ActivityRecord
	extends Omit<Activity, "dueAt" | "completedAt" | "remindedAt" | "createdAt"> {
	dueAt?: Date | null;
	completedAt?: Date | null;
	remindedAt?: Date | null;
	createdAt: Date;
}

import { z } from "zod";
const text = z.string().trim().max(500);
const optionalText = text.nullable().optional();
const relation = z.string().min(1).max(200).nullable().optional();
const date = z.iso.datetime({ offset: true }).nullable().optional();
export const idSchema = z.object({ id: z.string().min(1).max(200) });
export const paginationSchema = z.object({
	limit: z.coerce.number().int().min(1).max(200).default(50),
	offset: z.coerce.number().int().min(0).default(0),
});
export const createContactSchema = z.object({
	firstName: text.min(1),
	lastName: optionalText,
	email: z.email().max(320).nullable().optional(),
	phone: optionalText,
	company: optionalText,
	companyId: relation,
	title: optionalText,
	notes: z.string().max(20000).nullable().optional(),
	tags: z.array(z.string().trim().min(1).max(100)).max(100).default([]),
	customFields: z
		.record(z.string().min(1).max(100), z.string().max(2000))
		.refine((v) => Object.keys(v).length <= 100, "At most 100 custom fields")
		.default({}),
});
export const updateContactSchema = createContactSchema.partial().extend({
	tags: createContactSchema.shape.tags.removeDefault().optional(),
	customFields: createContactSchema.shape.customFields
		.removeDefault()
		.optional(),
});
export const listContactsSchema = paginationSchema.extend({
	search: text.optional(),
	tag: text.optional(),
	companyId: z.string().optional(),
});
export const createCompanySchema = z.object({
	name: text.min(1),
	domain: optionalText,
	phone: optionalText,
	notes: z.string().max(20000).nullable().optional(),
});
export const updateCompanySchema = createCompanySchema.partial();
export const listCompaniesSchema = paginationSchema.extend({
	search: text.optional(),
});
export const createPipelineSchema = z.object({
	name: text.min(1),
	slug: z
		.string()
		.regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/)
		.max(200)
		.optional(),
	stages: z
		.array(text.min(1))
		.min(1)
		.max(30)
		.default(["Lead", "Qualified", "Proposal", "Closed"]),
});
export const createDealSchema = z.object({
	title: text.min(1),
	value: z.number().finite().min(0).nullable().optional(),
	currency: z
		.string()
		.regex(/^[A-Z]{3}$/)
		.default("USD"),
	stage: z.string().min(1),
	pipelineId: z.string().min(1),
	contactId: relation,
	companyId: relation,
	closeDate: date,
	status: z.enum(["open", "won", "lost"]).default("open"),
});
export const updateDealSchema = createDealSchema
	.omit({ stage: true, pipelineId: true })
	.partial()
	.extend({
		currency: createDealSchema.shape.currency.removeDefault().optional(),
		status: createDealSchema.shape.status.removeDefault().optional(),
	});
export const moveDealSchema = z.object({
	stage: z.string().min(1),
	order: z.number().finite().min(0).optional(),
});
export const listDealsSchema = paginationSchema.extend({
	pipelineId: z.string().optional(),
	contactId: z.string().optional(),
	companyId: z.string().optional(),
	status: z.enum(["open", "won", "lost"]).optional(),
});
export const createActivitySchema = z
	.object({
		type: z.enum(["note", "call", "email", "meeting"]),
		body: z.string().trim().min(1).max(20000),
		contactId: relation,
		dealId: relation,
		dueAt: date,
	})
	.refine(
		(v) => !!(v.contactId || v.dealId),
		"An activity needs a contact or deal",
	);
export const updateActivitySchema = z.object({
	body: z.string().trim().min(1).max(20000).optional(),
	dueAt: date,
	completedAt: date,
});
export const listActivitiesSchema = paginationSchema.extend({
	contactId: z.string().optional(),
	dealId: z.string().optional(),
});

import { definePermissions, permission } from "@btst/stack/authorization";
import { z } from "zod";
const record = z.object({ id: z.string() });
const deal = z.object({
	id: z.string(),
	pipelineId: z.string(),
	contactId: z.string().nullable(),
	companyId: z.string().nullable(),
});
/** CRM operations are private by default; applications grant access through their shared authorization rules. */
export const crmPermissions = definePermissions("crm", {
	contact: {
		read: permission(),
		create: permission(),
		update: permission(record),
		delete: permission(record),
	},
	company: {
		read: permission(),
		create: permission(),
		update: permission(record),
		delete: permission(record),
	},
	deal: {
		read: permission(),
		create: permission(
			z.object({
				pipelineId: z.string(),
				stage: z.string(),
				contactId: z.string().nullable(),
				companyId: z.string().nullable(),
			}),
		),
		update: permission(deal),
		delete: permission(deal),
		move: permission(deal.extend({ targetStage: z.string() })),
	},
	pipeline: { read: permission(), create: permission() },
	activity: {
		read: permission(),
		create: permission(
			z.object({
				contactId: z.string().nullable(),
				dealId: z.string().nullable(),
			}),
		),
		update: permission(record),
		delete: permission(record),
	},
	reminder: { run: permission() },
});

"use client";
import { useState, type FormEvent } from "react";
import { PermissionAccess } from "@btst/stack/context";
import { useRegisterPageAIContext } from "@btst/stack/plugins/ai-chat/client/context";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import {
	useActivities,
	useCreateActivity,
	useUpdateActivity,
	useDeleteActivity,
} from "@btst/stack/plugins/crm/client/hooks";
import { crmPermissions } from "../../permissions";
import type { ActivityInput } from "@btst/stack/plugins/crm/query-keys";
import {
	Field,
	Feedback,
	DeleteRecord,
	Pagination,
	selectClass,
	useCrmAction,
} from "./shared";

export function ActivityTimeline({
	contactId,
	dealId,
	description,
}: {
	contactId?: string;
	dealId?: string;
	description: string;
}) {
	const [offset, setOffset] = useState(0);
	const { data } = useActivities({ contactId, dealId, limit: 25, offset });
	const create = useCreateActivity();
	const update = useUpdateActivity();
	const remove = useDeleteActivity();
	const [logging, setLogging] = useState(false);
	const action = useCrmAction();
	useRegisterPageAIContext({
		routeName: contactId ? "crm-contact-detail" : "crm-deal-detail",
		pageDescription:
			`${description}\nRecent activities:\n${data.items.map((a) => `${a.type}: ${a.body}${a.dueAt ? ` Follow-up due ${a.dueAt}` : ""}`).join("\n")}`.slice(
				0,
				16000,
			),
		suggestions: [
			"Summarize this relationship's history",
			"Draft a follow-up email",
			"Log a call note",
		],
		clientTools: {
			logCrmActivity: async (input: ActivityInput) => {
				await create.mutateAsync({ ...input, contactId, dealId });
				return { success: true, message: "Activity saved" };
			},
		},
	});
	const save = (event: FormEvent<HTMLFormElement>) => {
		event.preventDefault();
		const form = event.currentTarget;
		const fields = new FormData(form);
		const due = String(fields.get("dueAt") || "");
		void action.run(async () => {
			await create.mutateAsync({
				type: String(fields.get("type")) as ActivityInput["type"],
				body: String(fields.get("body")),
				contactId,
				dealId,
				dueAt: due ? new Date(due).toISOString() : null,
			});
			form.reset();
			setLogging(false);
		}, "Activity saved");
	};
	return (
		<section className="min-w-0 space-y-5" aria-label="Activity timeline">
			<div className="flex flex-wrap items-center justify-between gap-3">
				<h2 className="text-xl font-semibold">Activity timeline</h2>
				<PermissionAccess
					permission={crmPermissions.activity.create({
						contactId: contactId ?? null,
						dealId: dealId ?? null,
					})}
				>
					<Button
						className="min-h-11"
						variant="outline"
						onClick={() => setLogging(!logging)}
					>
						Log activity
					</Button>
				</PermissionAccess>
			</div>
			<Feedback {...action} />
			{logging && (
				<form className="space-y-4 rounded-lg border p-4" onSubmit={save}>
					<div className="grid gap-4 sm:grid-cols-2">
						<Field label="Type">
							{(id) => (
								<select id={id} name="type" className={selectClass}>
									<option value="note">Note</option>
									<option value="call">Call</option>
									<option value="email">Email</option>
									<option value="meeting">Meeting</option>
								</select>
							)}
						</Field>
						<Field label="Follow-up due">
							{(id) => <Input id={id} name="dueAt" type="datetime-local" />}
						</Field>
					</div>
					<Field label="Activity details">
						{(id) => (
							<Textarea
								id={id}
								name="body"
								required
								maxLength={20000}
								rows={4}
							/>
						)}
					</Field>
					<div className="flex gap-3">
						<Button
							type="submit"
							className="min-h-11"
							disabled={create.isPending}
						>
							Save activity
						</Button>
						<Button
							type="button"
							variant="outline"
							className="min-h-11"
							onClick={() => setLogging(false)}
						>
							Cancel
						</Button>
					</div>
				</form>
			)}
			{data.items.length ? (
				<ol className="divide-y">
					{data.items.map((activity) => (
						<li key={activity.id} className="space-y-3 py-5">
							<div className="flex flex-wrap items-baseline justify-between gap-2">
								<h3 className="font-medium capitalize">{activity.type}</h3>
								<time
									className="text-sm text-muted-foreground"
									dateTime={activity.createdAt}
								>
									{new Date(activity.createdAt).toLocaleString()}
								</time>
							</div>
							<p className="whitespace-pre-wrap break-words text-sm leading-6">
								{activity.body}
							</p>
							{activity.dueAt && (
								<p className="text-sm">
									{activity.completedAt ? "Completed" : "Follow-up due"}:{" "}
									<time dateTime={activity.completedAt ?? activity.dueAt}>
										{new Date(
											activity.completedAt ?? activity.dueAt,
										).toLocaleString()}
									</time>
								</p>
							)}
							<div className="flex flex-wrap gap-2">
								{activity.dueAt && (
									<PermissionAccess
										permission={crmPermissions.activity.update({
											id: activity.id,
										})}
									>
										<Button
											variant="outline"
											className="min-h-11"
											disabled={update.isPending}
											onClick={() =>
												void action.run(
													async () => {
														await update.mutateAsync({
															id: activity.id,
															data: {
																completedAt: activity.completedAt
																	? null
																	: new Date().toISOString(),
															},
														});
													},
													activity.completedAt
														? "Follow-up reopened"
														: "Follow-up completed",
												)
											}
										>
											{activity.completedAt
												? "Reopen follow-up"
												: "Complete follow-up"}
										</Button>
									</PermissionAccess>
								)}
								<PermissionAccess
									permission={crmPermissions.activity.delete({
										id: activity.id,
									})}
								>
									<DeleteRecord
										label="Delete activity"
										description="This activity will be removed from the timeline."
										pending={remove.isPending}
										onDelete={() =>
											void action.run(async () => {
												await remove.mutateAsync(activity.id);
											}, "Activity deleted")
										}
									/>
								</PermissionAccess>
							</div>
						</li>
					))}
				</ol>
			) : (
				<p className="py-6 text-muted-foreground">
					No activities yet. Log a note, call, email, or meeting to start the
					timeline.
				</p>
			)}
			<Pagination offset={offset} total={data.total} onChange={setOffset} />
		</section>
	);
}

"use client";
import type { FormEvent } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
	useCompanies,
	useContacts,
	useCreateDeal,
	useUpdateDeal,
} from "@btst/stack/plugins/crm/client/hooks";
import type { Deal, Pipeline } from "../../types";
import type { DealInput } from "@btst/stack/plugins/crm/query-keys";
import {
	SelectedCompanyOption,
	SelectedContactOption,
} from "./relation-options";
import { Field, Feedback, fullName, selectClass, useCrmAction } from "./shared";
export function DealForm({
	pipeline,
	stage,
	deal,
	onSaved,
	onCancel,
}: {
	pipeline: Pipeline;
	stage?: string;
	deal?: Deal;
	onSaved: (deal: Deal) => void | Promise<void>;
	onCancel: () => void;
}) {
	const { data: contacts } = useContacts({ limit: 200 });
	const { data: companies } = useCompanies({ limit: 200 });
	const create = useCreateDeal();
	const update = useUpdateDeal();
	const action = useCrmAction();
	const save = (event: FormEvent<HTMLFormElement>) => {
		event.preventDefault();
		const fields = new FormData(event.currentTarget);
		void action.run(async () => {
			const value = String(fields.get("value") || "");
			const date = String(fields.get("closeDate") || "");
			const input: Omit<DealInput, "pipelineId" | "stage"> = {
				title: String(fields.get("title")),
				value: value ? Number(value) : null,
				currency: String(fields.get("currency")).toUpperCase(),
				contactId: String(fields.get("contactId") || "") || null,
				companyId: String(fields.get("companyId") || "") || null,
				closeDate: date ? new Date(`${date}T12:00:00Z`).toISOString() : null,
				status: String(fields.get("status") || "open") as DealInput["status"],
			};
			const saved = deal
				? await update.mutateAsync({ id: deal.id, data: input })
				: await create.mutateAsync({
						...input,
						pipelineId: pipeline.id,
						stage: String(fields.get("stage")),
					});
			await onSaved(saved);
		});
	};
	return (
		<form className="max-w-3xl space-y-4 rounded-lg border p-5" onSubmit={save}>
			<h2 className="text-xl font-medium">{deal ? "Edit deal" : "New deal"}</h2>
			<Feedback {...action} />
			<div className="grid gap-4 sm:grid-cols-2">
				<Field label="Deal title">
					{(id) => (
						<Input
							id={id}
							name="title"
							required
							maxLength={500}
							defaultValue={deal?.title}
						/>
					)}
				</Field>
				<Field label="Value">
					{(id) => (
						<Input
							id={id}
							name="value"
							type="number"
							min={0}
							step="any"
							defaultValue={deal?.value ?? ""}
						/>
					)}
				</Field>
				<Field label="Currency">
					{(id) => (
						<Input
							id={id}
							name="currency"
							required
							pattern="[A-Za-z]{3}"
							maxLength={3}
							defaultValue={deal?.currency ?? "USD"}
						/>
					)}
				</Field>
				<Field label="Close date">
					{(id) => (
						<Input
							id={id}
							name="closeDate"
							type="date"
							defaultValue={deal?.closeDate?.slice(0, 10) ?? ""}
						/>
					)}
				</Field>
				{!deal && (
					<Field label="Stage">
						{(id) => (
							<select
								id={id}
								name="stage"
								className={selectClass}
								required
								defaultValue={stage ?? pipeline.columns[0]?.id}
							>
								{pipeline.columns.map((column) => (
									<option value={column.id} key={column.id}>
										{column.title}
									</option>
								))}
							</select>
						)}
					</Field>
				)}
				<Field label="Status">
					{(id) => (
						<select
							id={id}
							name="status"
							className={selectClass}
							defaultValue={deal?.status ?? "open"}
						>
							<option value="open">Open</option>
							<option value="won">Won</option>
							<option value="lost">Lost</option>
						</select>
					)}
				</Field>
				<Field label="Contact">
					{(id) => (
						<select
							id={id}
							name="contactId"
							className={selectClass}
							defaultValue={deal?.contactId ?? ""}
						>
							<option value="">No linked contact</option>
							{deal?.contactId &&
								!contacts.items.some(
									(contact) => contact.id === deal.contactId,
								) && <SelectedContactOption id={deal.contactId} />}
							{contacts.items.map((contact) => (
								<option key={contact.id} value={contact.id}>
									{fullName(contact)}
								</option>
							))}
						</select>
					)}
				</Field>
				<Field label="Company">
					{(id) => (
						<select
							id={id}
							name="companyId"
							className={selectClass}
							defaultValue={deal?.companyId ?? ""}
						>
							<option value="">No linked company</option>
							{deal?.companyId &&
								!companies.items.some(
									(company) => company.id === deal.companyId,
								) && <SelectedCompanyOption id={deal.companyId} />}
							{companies.items.map((company) => (
								<option key={company.id} value={company.id}>
									{company.name}
								</option>
							))}
						</select>
					)}
				</Field>
			</div>
			<div className="flex gap-3">
				<Button
					type="submit"
					className="min-h-11"
					disabled={create.isPending || update.isPending}
				>
					Save deal
				</Button>
				<Button
					type="button"
					className="min-h-11"
					variant="outline"
					onClick={onCancel}
				>
					Cancel
				</Button>
			</div>
		</form>
	);
}

