									<dt className="text-muted-foreground">Company</dt>
									<dd className="mt-1">
										<LinkedCompany id={deal.companyId} />
									</dd>
								</div>
							)}
							{deal.closeDate && (
								<div>
									<dt className="text-muted-foreground">Close date</dt>
									<dd className="mt-1">
										<time dateTime={deal.closeDate}>
											{new Date(deal.closeDate).toLocaleDateString()}
										</time>
									</dd>
								</div>
							)}
						</dl>
						<Field label="Stage">
							{(fieldId) => (
								<select
									id={fieldId}
									className={selectClass}
									value={deal.stage}
									disabled={move.isPending}
									onChange={(event) => {
										const stage = event.target.value;
										void action.run(async () => {
											await move.mutateAsync({ id, stage });
										}, "Deal stage updated");
									}}
								>
									{pipeline.columns.map((column) =>
										column.id === deal.stage ? (
											<option key={column.id} value={column.id}>
												{column.title}
											</option>
										) : (
											<PermissionAccess
												key={column.id}
												permission={crmPermissions.deal.move({
													...facts,
													targetStage: column.id,
												})}
											>
												<option value={column.id}>{column.title}</option>
											</PermissionAccess>
										),
									)}
								</select>
							)}
						</Field>
					</section>
					<PermissionAccess permission={crmPermissions.deal.delete(facts)}>
						<DeleteRecord
							label="Delete deal"
							description="This deal and its pipeline card will be removed."
							pending={remove.isPending}
							onDelete={() =>
								void action.run(async () => {
									await remove.mutateAsync(id);
									await navigate(`crm/pipeline/${pipeline.id}`);
								})
							}
						/>
					</PermissionAccess>
				</aside>
				<ActivityTimeline
					dealId={id}
					description={`Deal: ${JSON.stringify(deal)}\nPipeline: ${pipeline.name}\nStage: ${pipeline.columns.find((c) => c.id === deal.stage)?.title}`}
				/>
			</div>
		</CrmPage>
	);
}

"use client";
import { useEffect, useState, type FormEvent } from "react";
import { usePluginSiteNavigation } from "@btst/stack/context";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import {
	useContact,
	useCompanies,
	useCreateContact,
	useUpdateContact,
} from "@btst/stack/plugins/crm/client/hooks";
import type { Contact } from "../../../types";
import type { ContactInput } from "@btst/stack/plugins/crm/query-keys";
import { SelectedCompanyOption } from "../relation-options";
import { CRM_PLUGIN_ID } from "../../constants";
import { CrmPage, Field, Feedback, selectClass, useCrmAction } from "../shared";
export function EditContactPage({ id }: { id?: string }) {
	return id ? <ExistingContact id={id} /> : <ContactForm />;
}
function ExistingContact({ id }: { id: string }) {
	const { data } = useContact(id);
	return <ContactForm key={data.id} contact={data} />;
}
function ContactForm({ contact }: { contact?: Contact }) {
	const [hydrated, setHydrated] = useState(false);
	useEffect(() => setHydrated(true), []);
	const { data: companies } = useCompanies({ limit: 200 });
	const create = useCreateContact();
	const update = useUpdateContact();
	const { Link, resolve, navigate } = usePluginSiteNavigation(CRM_PLUGIN_ID);
	const action = useCrmAction();
	const [customFields, setCustomFields] = useState(
		Object.entries(contact?.customFields ?? {}),
	);
	const save = (event: FormEvent<HTMLFormElement>) => {
		event.preventDefault();
		const fields = new FormData(event.currentTarget);
		void action.run(async () => {
			const companyId = String(fields.get("companyId") || "");
			const input: ContactInput = {
				firstName: String(fields.get("firstName")),
				lastName: String(fields.get("lastName") || ""),
				email: String(fields.get("email") || "") || null,
				phone: String(fields.get("phone") || ""),
				companyId: companyId || null,
				company:
					companies.items.find((c) => c.id === companyId)?.name ??
					String(fields.get("company") || ""),
				title: String(fields.get("title") || ""),
				tags: String(fields.get("tags") || "")
					.split(",")
					.map((t) => t.trim())
					.filter(Boolean),
				notes: String(fields.get("notes") || ""),
				customFields: Object.fromEntries(
					customFields
						.filter(([key]) => key.trim())
						.map(([key, value]) => [key.trim(), value]),
				),
			};
			const saved = contact
				? await update.mutateAsync({ id: contact.id, data: input })
				: await create.mutateAsync(input);
			await navigate(`crm/contacts/${saved.id}`);
		});
	};
	return (
		<CrmPage title={contact ? "Edit contact" : "New contact"}>
			<Feedback {...action} />
			<form
				method="post"
				data-hydrated={hydrated}
				className="max-w-3xl space-y-6"
				onSubmit={save}
			>
				<fieldset disabled={!hydrated} className="space-y-6">
					<div className="grid gap-4 sm:grid-cols-2">
						{(
							[
								["firstName", "First name"],
								["lastName", "Last name"],
								["email", "Email"],
								["phone", "Phone"],
								["title", "Job title"],
							] as const
						).map(([name, label]) => (
							<Field key={name} label={label}>
								{(id) => (
									<Input
										id={id}
										name={name}
										type={
											name === "email"
												? "email"
												: name === "phone"
													? "tel"
													: "text"
										}
										required={name === "firstName"}
										maxLength={name === "email" ? 320 : 500}
										defaultValue={contact?.[name] ?? ""}
									/>
								)}
							</Field>
						))}
						<Field label="Company">
							{(id) => (
								<select
									id={id}
									name="companyId"
									className={selectClass}
									defaultValue={contact?.companyId ?? ""}
								>
									<option value="">No linked company</option>
									{contact?.companyId &&
										!companies.items.some(
											(company) => company.id === contact.companyId,
										) && <SelectedCompanyOption id={contact.companyId} />}
									{companies.items.map((company) => (
										<option key={company.id} value={company.id}>
											{company.name}
										</option>
									))}
								</select>
							)}
						</Field>
						<Field
							label="Company name"
							hint="Use a name without linking a company record."
						>
							{(id) => (
								<Input
									id={id}
									name="company"
									maxLength={500}
									defaultValue={contact?.company ?? ""}
								/>
							)}
						</Field>
						<Field label="Tags" hint="Separate tags with commas.">
							{(id) => (
								<Input
									id={id}
									name="tags"
									defaultValue={contact?.tags.join(", ")}
								/>
							)}
						</Field>
					</div>
					<Field label="Notes">
						{(id) => (
							<Textarea
								id={id}
								name="notes"
								rows={5}
								maxLength={20000}
								defaultValue={contact?.notes ?? ""}
							/>
						)}
					</Field>
					<fieldset className="space-y-3">
						<legend className="mb-3 text-sm font-medium">Custom fields</legend>
						{customFields.map(([key, value], index) => (
							<div
								key={index}
								className="grid items-end gap-3 sm:grid-cols-[1fr_2fr_auto]"
							>
								<Field label={`Field name ${index + 1}`}>
									{(id) => (
										<Input
											id={id}
											value={key}
											maxLength={100}
											required
											onChange={(e) =>
												setCustomFields((rows) =>
													rows.map((row, i) =>
														i === index ? [e.target.value, row[1]!] : row,
													),
												)
											}
										/>
									)}
								</Field>
								<Field label={`Field value ${index + 1}`}>
									{(id) => (
										<Input
											id={id}
											value={value}
											maxLength={2000}
											onChange={(e) =>
												setCustomFields((rows) =>
													rows.map((row, i) =>
														i === index ? [row[0]!, e.target.value] : row,
													),
												)
											}
										/>
									)}
								</Field>
								<Button
									type="button"
									className="min-h-11"
									variant="outline"
									onClick={() =>
										setCustomFields((rows) =>
											rows.filter((_, i) => i !== index),
										)
									}
								>
									Remove field {index + 1}
								</Button>
							</div>
						))}
						<Button
							type="button"
							variant="outline"
							className="min-h-11"
							disabled={customFields.length >= 100}
							onClick={() => setCustomFields((rows) => [...rows, ["", ""]])}
						>
							Add custom field
						</Button>
					</fieldset>
					<div className="flex gap-3">
						<Button
							type="submit"
							className="min-h-11"
							disabled={!hydrated || create.isPending || update.isPending}
						>
							Save contact
						</Button>
						<Button asChild variant="outline" className="min-h-11">
							<Link
								href={
									resolve(
										contact ? `crm/contacts/${contact.id}` : "crm/contacts",
									).href
								}
							>
								Cancel
							</Link>
						</Button>
					</div>
				</fieldset>
			</form>
		</CrmPage>
	);
}

"use client";
import { useEffect, useRef, useState } from "react";
import { GripVertical } from "lucide-react";
import { PermissionAccess, usePluginSiteNavigation } from "@btst/stack/context";
import { Button } from "@/components/ui/button";
import * as Kanban from "@/components/ui/kanban";
import { KanbanBoard } from "@btst/stack/plugins/kanban/client/components";
import type { Pipeline } from "../../../types";
type SerializedTask = Pipeline["columns"][number]["tasks"][number];
import { usePipeline, useMoveDeal } from "@btst/stack/plugins/crm/client/hooks";
import { crmPermissions } from "../../../permissions";
import { CRM_PLUGIN_ID } from "../../constants";
import { CrmPage, Feedback, money, useCrmAction } from "../shared";
import { DealForm } from "../deal-form";
export function PipelinePage({ pipelineId }: { pipelineId: string }) {
	const { data: pipeline, refetch } = usePipeline(pipelineId);
	const move = useMoveDeal();
	const [adding, setAdding] = useState<string>();
	const { Link, resolve } = usePluginSiteNavigation(CRM_PLUGIN_ID);
	const action = useCrmAction();
	const dealMap = new Map(pipeline.deals.map((deal) => [deal.taskId, deal]));
	const source = Object.fromEntries(
		pipeline.columns.map((column) => [
			column.id,
			column.tasks.filter((task) => dealMap.has(task.id)),
		]),
	);
	const [state, setState] = useState(source);
	const stateRef = useRef(state);
	const busy = useRef(false);
	useEffect(() => {
		const next = Object.fromEntries(
			pipeline.columns.map((column) => [
				column.id,
				column.tasks.filter((task) =>
					pipeline.deals.some((deal) => deal.taskId === task.id),
				),
			]),
		);
		stateRef.current = next;
		setState(next);
	}, [pipeline]);
	const change = (next: Record<string, SerializedTask[]>) => {
		stateRef.current = next;
		setState(next);
	};
	const persist = () => {
		queueMicrotask(() => {
			const next = stateRef.current;
			if (busy.current) return;
			const changes = Object.entries(next).flatMap(([stage, tasks]) =>
				tasks.flatMap((task, index) => {
					const deal = dealMap.get(task.id);
					const original = source[stage]?.findIndex((t) => t.id === task.id);
					return deal && (deal.stage !== stage || original !== index)
						? [{ id: deal.id, stage, order: index }]
						: [];
				}),
			);
			if (!changes.length) return;
			busy.current = true;
			void action.run(async () => {
				try {
					for (const change of changes) await move.mutateAsync(change);
				} finally {
					busy.current = false;
					await refetch();
				}
			}, "Deal stage updated");
		});
	};
	return (
		<CrmPage
			title={pipeline.name}
			description="Move deals between stages by dragging their handles, or choose a stage from a deal's detail page."
			action={
				<PermissionAccess
					permission={crmPermissions.deal.create({
						pipelineId,
						stage: pipeline.columns[0]?.id ?? "",
						contactId: null,
						companyId: null,
					})}
				>
					<Button
						className="min-h-11"
						onClick={() => setAdding(pipeline.columns[0]?.id)}
					>
						New deal
					</Button>
				</PermissionAccess>
			}
		>
			<Feedback {...action} />
			{adding && (
				<DealForm
					pipeline={pipeline}
					stage={adding}
					onSaved={() => setAdding(undefined)}
					onCancel={() => setAdding(undefined)}
				/>
			)}
			<KanbanBoard
				boardId={pipeline.id}
				columns={pipeline.columns}
				kanbanState={state}
				onKanbanChange={change}
				onDragEnd={persist}
				onDragCancel={() => {
					stateRef.current = source;
					setState(source);
				}}
				onAddTask={setAdding}
				onEditTask={() => {}}
				onEditColumn={() => {}}
				onDeleteColumn={() => {}}
				renderColumn={(column) => (
					<Kanban.Column
						value={column.id}
						className="bg-muted/40 dark:bg-muted/40"
					>
						<div className="flex items-baseline justify-between gap-3 px-1 py-2">
							<h2 className="font-semibold">{column.title}</h2>
							<span className="text-sm text-muted-foreground">
								{column.tasks.length}
							</span>
						</div>
						<div className="space-y-3">
							{column.tasks.map((task) => {
								const deal = dealMap.get(task.id);
								if (!deal) return null;
								const facts = {
									id: deal.id,
									pipelineId,
									contactId: deal.contactId ?? null,
									companyId: deal.companyId ?? null,
								};
								return (
									<Kanban.Item key={task.id} value={task.id} asChild>
										<article className="space-y-3 rounded-md border bg-card p-3">
											<div className="flex items-start gap-2">
												<PermissionAccess
													permission={crmPermissions.deal.move({
														...facts,
														targetStage: column.id,
													})}
												>
													<Kanban.ItemHandle asChild disabled={move.isPending}>
														<Button
															variant="ghost"
															className="min-h-11 min-w-11 shrink-0"
															disabled={move.isPending}
															aria-label={`Move deal ${deal.title}`}
														>
															<GripVertical className="size-4" />
														</Button>
													</Kanban.ItemHandle>
												</PermissionAccess>
												<Link
													href={resolve(`crm/deals/${deal.id}`).href}
													className="inline-flex min-h-11 items-center break-words font-medium hover:underline"
												>
													{deal.title}
												</Link>
											</div>
											<div className="flex flex-wrap items-center justify-between gap-2 text-sm">
												<span className="font-medium tabular-nums">
													{money(deal.value, deal.currency)}
												</span>
												<span className="text-muted-foreground capitalize">
													{deal.status}
												</span>
											</div>
											{deal.closeDate && (
												<p className="text-xs text-muted-foreground">
													Closes{" "}
													<time dateTime={deal.closeDate}>
														{new Date(deal.closeDate).toLocaleDateString()}
													</time>
												</p>
											)}
										</article>
									</Kanban.Item>
								);
							})}
						</div>
						{!column.tasks.length && (
							<p className="py-6 text-center text-sm text-muted-foreground">
								No deals in this stage.
							</p>
						)}
						<PermissionAccess
							permission={crmPermissions.deal.create({
								pipelineId,
								stage: column.id,
								contactId: null,
								companyId: null,
							})}
						>
							<Button
								variant="ghost"
								className="min-h-11 w-full"
								onClick={() => setAdding(column.id)}
							>
								Add deal to {column.title}
							</Button>
						</PermissionAccess>
					</Kanban.Column>
				)}
			/>
		</CrmPage>
	);
}

"use client";
import { useState, type FormEvent } from "react";
