					>
						{(id) => (
							<Input
								id={id}
								name="stages"
								required
								defaultValue="Lead, Qualified, Proposal, Closed"
							/>
						)}
					</Field>
					<div className="flex gap-3">
						<Button
							type="submit"
							className="min-h-11"
							disabled={create.isPending}
